import os

def verify_changes(root_dir):
    results = []
    for root, dirs, files in os.walk(root_dir):
        if os.path.basename(root) == 'yedek':
            continue
        for file in files:
            if not file.endswith('.ini'):
                continue
            file_path = os.path.join(root, file)
            results.append(file_path)
    return results

def check_file_content(file_path):
    print(f"Kontrol ediliyor: {file_path}")
    try:
        with open(file_path, 'rb') as f:
            raw = f.read()

        # BOM kontrolü
        has_bom = raw.startswith(b'\xef\xbb\xbf')
        content = raw.decode('utf-8-sig')
        lines = content.splitlines()

        in_db_section = False
        found_port_5432 = False
        found_port_6543 = False
        other_ports_changed = False

        for line in lines:
            stripped = line.strip().lower()
            if stripped == '[veritabani]':
                in_db_section = True
                continue
            elif stripped.startswith('[') and stripped != '[veritabani]':
                in_db_section = False

            if in_db_section:
                # Port kontrolü (basitçe)
                if 'port' in stripped:
                    if '5432' in stripped:
                        found_port_5432 = True
                    if '6543' in stripped:
                        found_port_6543 = True

        status = "OK" if (not found_port_5432 and found_port_6543) or (not found_port_5432 and not found_port_6543) else "HATA"
        # Eğer 5432 hala varsa ama 6543 yoksa veya tam tersi durumlar...
        # Asıl kural: [veritabani] içindeki port 5432 ise 6543 olmalı.

        print(f"  - BOM: {'Var' if has_bom else 'Yok'}")
        print(f"  - [veritabani] içinde 5432 bulundu mu? {found_port_5432}")
        print(f"  - [veritabani] içinde 6543 bulundu mu? {found_port_6543}")

